fn primary_group_offsets_from_cluster_offsets(
    cluster_offsets: &[usize],
    secondary_clusters: usize,
) -> Vec<usize> {
    let mut primary_offsets = Vec::with_capacity(PRIMARY_CLUSTERS + 1);
