    secondary_clusters: usize,
    primary_centroids: &'a [f32],
    secondary_centroids: &'a [f32],
) -> &'a [f32] {
    match scope {
        CoarsePrescoreScope::Cluster => {
            &secondary_centroids[cluster_id * DIM..(cluster_id + 1) * DIM]
