        }
    }
}

#[inline(always)]
fn count_active_primary_groups(scan_ranges: &[ScanRange], secondary_clusters: usize) -> usize {
    let mut seen = [false; PRIMARY_CLUSTERS];
    let mut active = 0usize;
    for range in scan_ranges {
        let primary_id = range.cluster_id / secondary_clusters;
        if !seen[primary_id] {
            seen[primary_id] = true;
            active += 1;
        }
    }
    active
}

